import{_ as t,o as i,c as s,ao as a}from"./chunks/framework.C8dQ12Ma.js";const k=JSON.parse('{"title":"Integrations","description":"","frontmatter":{},"headers":[],"relativePath":"guides/integrations.md","filePath":"guides/integrations.md","lastUpdated":null}'),o={name:"guides/integrations.md"};function n(l,e,r,d,h,p){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="Integrations" tabindex="-1">Integrations <a class="header-anchor" href="#Integrations" aria-label="Permalink to &quot;Integrations {#Integrations}&quot;">​</a></h1><p>CytoZoo&#39;s base package has <strong>zero runtime dependencies</strong>. Everything that needs an external package arrives through a Julia package extension, loaded automatically when you load the relevant package.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Extension</th><th style="text-align:right;">Loads with</th><th style="text-align:right;">Provides</th></tr></thead><tbody><tr><td style="text-align:right;"><code>SciMLBaseExt</code></td><td style="text-align:right;">SciMLBase / OrdinaryDiffEq</td><td style="text-align:right;"><code>ODEProblem</code> constructor, <a href="/CytoZoo.jl/dev/reference/api#CytoZoo.monitor_history"><code>monitor_history</code></a></td></tr><tr><td style="text-align:right;"><code>ForwardDiffExt</code></td><td style="text-align:right;">ForwardDiff</td><td style="text-align:right;">primal extraction for <code>connect</code> inputs</td></tr><tr><td style="text-align:right;"><code>ThunderboltExt</code></td><td style="text-align:right;">Thunderbolt</td><td style="text-align:right;"><a href="/CytoZoo.jl/dev/reference/api#CytoZoo.thunderbolt_model"><code>thunderbolt_model</code></a> tissue adapter</td></tr></tbody></table><p>You never load an extension directly — loading the trigger package is enough.</p><h2 id="SciMLBase:-Solving" tabindex="-1">SciMLBase: Solving <a class="header-anchor" href="#SciMLBase:-Solving" aria-label="Permalink to &quot;SciMLBase: Solving {#SciMLBase:-Solving}&quot;">​</a></h2><p>Loading any SciMLBase-based solver stack adds an <code>ODEProblem</code> constructor for any <code>AbstractCellModel</code>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CytoZoo, OrdinaryDiffEq</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ToRORd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prob  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ODEProblem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(model, (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prob</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tspan</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">(0.0, 500.0)</span></span></code></pre></div><p>The constructor defaults <code>u0</code> to <code>default_initial_state(model)</code> and <code>p</code> to <code>nothing</code>, and forwards any other keyword to <code>ODEProblem</code>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ODEProblem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(model, tspan; u0 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> my_state, p </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> my_spatial_context, saveat </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>This is also the entry point for solving a <a href="/CytoZoo.jl/dev/reference/api#CytoZoo.CoupledModel"><code>CoupledModel</code></a> — a coupling is a model, so it constructs a problem the same way.</p><p>The extension also provides <a href="/CytoZoo.jl/dev/reference/api#CytoZoo.monitor_history"><code>monitor_history</code></a>, the post-solve helper for derived observables. See <a href="./monitors">Derived Observables</a>.</p><h2 id="ForwardDiff:-Implicit-Solvers" tabindex="-1">ForwardDiff: Implicit Solvers <a class="header-anchor" href="#ForwardDiff:-Implicit-Solvers" aria-label="Permalink to &quot;ForwardDiff: Implicit Solvers {#ForwardDiff:-Implicit-Solvers}&quot;">​</a></h2><p>Implicit solvers pull in ForwardDiff, which loads this extension automatically. It exists for exactly one purpose: a <a href="/CytoZoo.jl/dev/reference/api#CytoZoo.connect"><code>connect</code></a> edge stages a source state into a receiver&#39;s <code>Float64</code> parameter slot, and a dual number cannot be stored there. The extension extracts the primal so the connect input is frozen within the Newton step.</p><p>You never call anything from this extension. But it changes what your results <em>mean</em>, and the consequences are serious enough to have their own page — <strong>derivatives taken through a <code>connect</code> edge are silently wrong</strong>. See <a href="./coupling/limitations">Coupling Limitations</a>.</p><p><code>share</code> edges are unaffected, because they flow through the state vector.</p><h2 id="Thunderbolt:-Tissue-Level-Simulation" tabindex="-1">Thunderbolt: Tissue-Level Simulation <a class="header-anchor" href="#Thunderbolt:-Tissue-Level-Simulation" aria-label="Permalink to &quot;Thunderbolt: Tissue-Level Simulation {#Thunderbolt:-Tissue-Level-Simulation}&quot;">​</a></h2><p><a href="https://github.com/termi-official/Thunderbolt.jl" target="_blank" rel="noreferrer">Thunderbolt.jl</a> solves tissue-scale electrophysiology, and its <code>MonodomainModel</code> requires an ionic model subtyping <code>Thunderbolt.AbstractIonicModel</code>. Rather than making CytoZoo depend on Thunderbolt, the extension defines an adapter, <code>CytoZooIonicModel</code>, and exposes it through <a href="/CytoZoo.jl/dev/reference/api#CytoZoo.thunderbolt_model"><code>thunderbolt_model</code></a>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CytoZoo, Thunderbolt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ionic </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> thunderbolt_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ToRORd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># use \`ionic\` with Thunderbolt.MonodomainModel(...)</span></span></code></pre></div><p>For spatially heterogeneous tissue, pass <code>overrides</code>. You do <strong>not</strong> construct the <a href="/CytoZoo.jl/dev/reference/api#CytoZoo.SpatialContext"><code>SpatialContext</code></a> yourself — the adapter builds one per cell from the mesh position Thunderbolt supplies:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">overrides </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (IKr_Multiplier </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (x, t) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.5</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ionic </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> thunderbolt_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ToRORd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); overrides)</span></span></code></pre></div><p>With <code>overrides = nothing</code> (the default) the adapter passes <code>p = nothing</code> straight through, so the non-spatial fast path is used and no spatial machinery is compiled in.</p><p>The adapter forwards the state count, transmembrane-potential index, and default initial state to Thunderbolt&#39;s equivalents, so a CytoZoo model behaves as a native ionic model.</p><p>Calling <a href="/CytoZoo.jl/dev/reference/api#CytoZoo.thunderbolt_model"><code>thunderbolt_model</code></a> without Thunderbolt loaded raises a <code>MethodError</code> — the function exists as a stub in the base package so it can be documented and referenced, but it has no methods until the extension loads.</p><h2 id="Writing-an-Adapter-for-Another-Package" tabindex="-1">Writing an Adapter for Another Package <a class="header-anchor" href="#Writing-an-Adapter-for-Another-Package" aria-label="Permalink to &quot;Writing an Adapter for Another Package {#Writing-an-Adapter-for-Another-Package}&quot;">​</a></h2><p>The Thunderbolt extension is the template for the <strong>ext fallback</strong> pattern: use it when an upstream package cannot depend on CytoZoo. Define a wrapper type in <code>ext/&lt;Pkg&gt;Ext.jl</code> that subtypes whatever the upstream framework requires, and forward the interface methods.</p><p>When you <em>do</em> control the model package, prefer native adherence instead — depend on CytoZoo and subtype <code>AbstractCardiacCellModel</code> directly. See <a href="./implementing_a_model">Implementing a Model</a>.</p><h2 id="Documenting-Extension-Functions" tabindex="-1">Documenting Extension Functions <a class="header-anchor" href="#Documenting-Extension-Functions" aria-label="Permalink to &quot;Documenting Extension Functions {#Documenting-Extension-Functions}&quot;">​</a></h2><p>A note for contributors, since it looks odd on first encounter. The docstrings for <a href="/CytoZoo.jl/dev/reference/api#CytoZoo.thunderbolt_model"><code>thunderbolt_model</code></a> and <a href="/CytoZoo.jl/dev/reference/api#CytoZoo.monitor_history"><code>monitor_history</code></a> live on <strong>stubs in <code>src/CytoZoo.jl</code></strong>, not in the extension modules. A docstring attached inside an extension registers in that module&#39;s documentation metadata rather than CytoZoo&#39;s, so Documenter&#39;s <code>Modules = [CytoZoo]</code> would never find it. Keep new extension entry points following the same pattern.</p><h2 id="See-Also" tabindex="-1">See Also <a class="header-anchor" href="#See-Also" aria-label="Permalink to &quot;See Also {#See-Also}&quot;">​</a></h2><ul><li><p><a href="./coupling/limitations">Coupling Limitations</a> — what ForwardDiffExt implies for gradients.</p></li><li><p><a href="./spatial">Spatial Heterogeneity</a> — the overrides Thunderbolt passes through.</p></li></ul>`,31)])])}const g=t(o,[["render",n]]);export{k as __pageData,g as default};
